using System.Security.Claims;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
namespace Decont;
public class MasterDraft {
 public Guid Id{get;set;}=Guid.NewGuid();public string Kind{get;set;}="";public string DataJson{get;set;}="{}";public string State{get;set;}="Draft";public long Version{get;set;}=1;public string AuthorId{get;set;}="";public string UpdatedBy{get;set;}="";public DateTime CreatedAt{get;set;}=DateTime.UtcNow;public DateTime UpdatedAt{get;set;}=DateTime.UtcNow;public Guid? MasterId{get;set;}
}
public record MasterDraftInput(MasterInput Data,long Version=0);
public static class ConfigurationDrafts {
 public static void Configure(ModelBuilder b){b.Entity<MasterDraft>().Property(x=>x.Version).IsConcurrencyToken();b.Entity<MasterDraft>().HasIndex(x=>new{x.Kind,x.State,x.UpdatedAt});b.Entity<MasterDraft>().HasOne<Master>().WithMany().HasForeignKey(x=>x.MasterId).OnDelete(DeleteBehavior.Restrict);}
 static void Permission(ClaimsPrincipal actor,MasterInput data){Guard.Require(Admin.Kinds.Contains(data.Kind),"master","Selectează un nomenclator valid.","Select a valid master type.");Guard.Require(data.Kind!="fx"&&!(data.Kind=="policies"&&VehicleDeductibility.IsCode(data.Code))||actor.IsInRole("Finance"),"forbidden","Doar Finance poate modifica un curs sau deductibilitatea auto.","Only Finance can change FX or vehicle deductibility.",403);}
 static void DraftInput(MasterInput data){Guard.Reason(data.Reason);Guard.Require(data.Json is {Length:>0 and <=16000}&&(data.Code?.Length??0)<=128&&(data.NameRo?.Length??0)<=256&&(data.NameEn?.Length??0)<=256&&data.Reason.Length<=2000,"size","Ciorna este goală sau prea mare.","Draft is empty or oversized.");try{using var doc=JsonDocument.Parse(data.Json);Guard.Require(doc.RootElement.ValueKind==JsonValueKind.Object,"json","Verifică datele ciornei.","Check draft data.");}catch(JsonException){throw new DomainException("json","Verifică datele ciornei.","Check draft data.");}}
 public static object View(MasterDraft d)=>new{d.Id,d.Kind,d.State,d.Version,d.AuthorId,d.UpdatedBy,d.CreatedAt,d.UpdatedAt,d.MasterId,data=Serialization.Read<MasterInput>(d.DataJson)};
 public static void Map(RouteGroupBuilder api){
  var routes=api.MapGroup("/configuration/drafts").RequireAuthorization(p=>p.RequireRole("Finance","Admin"));
  routes.MapGet("",async(Db db)=>{var rows=await db.MasterDrafts.OrderByDescending(d=>d.UpdatedAt).Take(200).ToListAsync();return rows.Select(View);});
  routes.MapPost("",async(MasterDraftInput i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Require(i.Data!=null,"input","Completează ciorna.","Complete the draft.");Permission(c.User,i.Data);DraftInput(i.Data);var draft=new MasterDraft{Kind=i.Data.Kind,DataJson=Serialization.Write(i.Data),AuthorId=Reports.Actor(c.User),UpdatedBy=Reports.Actor(c.User)};db.MasterDrafts.Add(draft);svc.Log(c.User,null,draft.Id.ToString(),"MasterDraftSaved",after:i.Data,reason:i.Data.Reason);return View(draft);}));
  routes.MapPut("/{id:guid}",async(Guid id,MasterDraftInput i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{var draft=await db.MasterDrafts.FindAsync(id)??throw new DomainException("missing","Ciornă inexistentă.","Draft not found.",404);Guard.Require(draft.State=="Draft"&&draft.Version==i.Version,"conflict","Ciorna s-a modificat sau a fost publicată. Reîncarcă.","Draft changed or was published. Reload.",409);Guard.Require(i.Data!=null&&draft.Kind==i.Data.Kind,"kind","Tipul ciornei nu se poate schimba.","Draft type cannot be changed.");Permission(c.User,i.Data);DraftInput(i.Data);var before=draft.DataJson;draft.DataJson=Serialization.Write(i.Data);draft.Version++;draft.UpdatedBy=Reports.Actor(c.User);draft.UpdatedAt=DateTime.UtcNow;svc.Log(c.User,null,id.ToString(),"MasterDraftSaved",before,i.Data,i.Data.Reason);return View(draft);}));
  routes.MapPost("/{id:guid}/publish",async(Guid id,VersionRequest i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Reason(i.Reason);var draft=await db.MasterDrafts.FindAsync(id)??throw new DomainException("missing","Ciornă inexistentă.","Draft not found.",404);Guard.Require(draft.State=="Draft"&&draft.Version==i.Version,"conflict","Ciorna s-a modificat sau a fost publicată. Reîncarcă.","Draft changed or was published. Reload.",409);var input=Serialization.Read<MasterInput>(draft.DataJson) with{Reason=i.Reason!};Permission(c.User,input);var master=await SpreadsheetImports.Create(input,db,svc,c);draft.State="Published";draft.MasterId=master.Id;draft.Version++;draft.UpdatedBy=Reports.Actor(c.User);draft.UpdatedAt=DateTime.UtcNow;svc.Log(c.User,null,id.ToString(),"MasterDraftPublished",after:new{master.Id,draft.Version},reason:i.Reason);return master;}));
  routes.MapPost("/{id:guid}/cancel",async(Guid id,VersionRequest i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Reason(i.Reason);var draft=await db.MasterDrafts.FindAsync(id)??throw new DomainException("missing","Ciornă inexistentă.","Draft not found.",404);Guard.Require(draft.State=="Draft"&&draft.Version==i.Version,"conflict","Ciorna s-a modificat. Reîncarcă.","Draft changed. Reload.",409);Permission(c.User,Serialization.Read<MasterInput>(draft.DataJson));draft.State="Cancelled";draft.Version++;draft.UpdatedBy=Reports.Actor(c.User);draft.UpdatedAt=DateTime.UtcNow;svc.Log(c.User,null,id.ToString(),"MasterDraftCancelled",reason:i.Reason);return View(draft);}));
 }
}
